head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusFooter]<br/>Footer 영역의 Cell 선택 시 포커스 기능을 활성화 할지 설정합니다. focusMode='none' 이면 Cell 선택이 동작하지 않으므로 동작하지 않습니다.",
    "validation" : [
        "true 설정 시 Footer 영역의 Cell 포커스 기능을 별도로 활성화 하며, focusMode 속성값에 맞게 포커스 및 CSS 클래스가 적용됩니다.",
        "true 설정 시 포커스 된 Cell 과 Row 에 selectedCellColor, selectedRowColor 속성이 적용됩니다.",
        "true 설정 시 Footer 영역에 dataDragSelect, focusDefaultColumn, useCtrlKey, useShiftKey, ctrlShiftKey 등의 속성이 Body 영역과 동일하게 적용됩니다.",
        "false (default) 설정 시 Footer 영역의 Cell 포커스 기능을 활성화하지 않습니다.",
        "focusMode='none' 이면 Cell 선택이 동작하지 않으므로 Footer 포커스 기능도 동작하지 않습니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 설정
    //  - con_focusFooter 가 미설정('') 이면 focusFooter 속성을 아예 부여하지 않음(기본값 false 동작)
    //  - 'true' / 'false' 면 해당 값으로 속성 부여
    //  - focusMode 는 가이드 명시대로 'none' 이면 동작하지 않으므로 기본값 유지(설정 안 함)
    //  - selectedCellColor / selectedRowColor 를 지정하여 footer cell 클릭 시 포커스 CSS 가 보이도록 구성
    let focusFooterVal = con_focusFooter.getText();
    let focusFooterAttr = (focusFooterVal === '') ? '' : ' focusFooter="' + focusFooterVal + '"';

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFocusFooter = (focusFooterVal === '') ? '미설정(기본값 false)' : focusFooterVal;
    $c.gcm.createLabel('label="focusFooter=' + lblFocusFooter + ' 로 GridView 생성 (Footer 2행 ft1~ft8, ft2/ft6 hidden / useShiftKey=true / selectedCellColor·selectedRowColor 지정)"', '', 'label1');

    // target 생성 (focusFooter 조건부 / Footer 2줄 / useShiftKey / 포커스 색상 지정)
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind"' + focusFooterAttr + ' useShiftKey="true" useCtrlKey="true" dataDragSelect="true" checkAllType="false" selectedCellColor="#1565c0" selectedRowColor="#bbdefb" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="focusFooter 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft1" value="footer1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft2" value="footer2(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="row4">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft5" value="footer5"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft6" value="footer6(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft7" value="footer7"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="ft8" value="footer8"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 현재 포커스된 Footer Cell 상태를 읽어 focusFooter 동작 결과를 출력 (상태 확인용 읽기 버튼)
scwin.btn_checkFocusedFooter_onclick = function () {
    // 엔진에 반영된 focusFooter 옵션값 확인
    wf_body_bottom.getObj("scwin").setReturnValue("target1.options.focusFooter : " + target1.options.focusFooter);

    // 포커스된 Footer Cell 정보 확인 (focusFooter=true 이고 Footer Cell 을 클릭한 경우에만 값이 반환됨)
    let rtn = target1.getFocusedFooterCell();
    let result = '';

    if (rtn && rtn.length > 0) {
        for (let i = 0; i < rtn.length; i++) {
            result += '{id:"' + rtn[i].id + '", rowIndex:' + rtn[i].rowIndex + ', colIndex:' + rtn[i].colIndex + '}';
            if (i < rtn.length - 1) {
                result += ', ';
            }
        }
        result = '[' + result + ']';
    } else {
        result = '[] (포커스된 Footer Cell 없음)';
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getFocusedFooterCell : " + result);
}
